# Fuente de verdad de la taxonomía de Orto (competencias + lecciones).
# Genera datos/competencias.json:  python3 orto/tools/competencias.py
# Cursos: 1-6 = 1º-6º de primaria, 7-10 = 1º-4º de ESO, 11 = bachillerato/adulto.
# r   = probabilidad de falta por aparición en alguien que NO domina la
#       competencia (para el OrtoScore); occ = apariciones por cada 100
#       palabras de prensa (las calcula tools/generar.mjs con el corpus; aquí,
#       estimación para las que no salen del corpus).
import json, os

BLOQUES = [
    ("ACE", "Acentuación", "🗣️"), ("BV", "B y V", "🅱️"), ("H", "La h", "🤫"), ("GJ", "G y J", "🦒"),
    ("LLY", "Ll e Y", "🌧️"), ("LET", "Otras letras (r, c, z, x…)", "🔤"), ("MAY", "Mayúsculas", "🔠"),
    ("PUN", "Puntuación", "❗"), ("JS", "Juntas o separadas", "🔗"), ("HOM", "Suenan igual (homófonos)", "👂"),
    ("ADU", "Las que más se escriben mal", "⚠️"),
]

def C(id, n, c, pre=(), r=0.3, occ=0.2, m=("elige",), regla="", ej=(), exc=(), truco=""):
    return dict(id=id, b=id.split(".")[0], n=n, c=c, pre=list(pre), r=r, occ=occ, m=list(m),
                lec=dict(regla=regla, ej=list(ej), exc=list(exc), truco=truco))

